           try_to_date(nullif(trim(received_date_raw), ''), 'MM/DD/YYYY'),
           try_to_timestamp_ntz(received_date_raw, 'YYYY-MM-DD"T"HH24:MI:SS')::date,
           try_to_timestamp_ntz(received_date_raw, 'YYYY-MM-DD HH24:MI:SS')::date) as received_date,
 coalesce(try_to_date(nullif(trim(decision_date_raw), ''), 'YYYY-MM-DD'),
           try_to_date(nullif(trim(decision_date_raw), ''), 'MM/DD/YYYY'),
           try_to_timestamp_ntz(decision_date_raw, 'YYYY-MM-DD"T"HH24:MI:SS')::date,
           try_to_timestamp_ntz(decision_date_raw, 'YYYY-MM-DD HH24:MI:SS')::date) as decision_date,
 coalesce(try_to_date(nullif(trim(begin_date_raw), ''), 'YYYY-MM-DD'),
           try_to_date(nullif(trim(begin_date_raw), ''), 'MM/DD/YYYY'),
           try_to_timestamp_ntz(begin_date_raw, 'YYYY-MM-DD"T"HH24:MI:SS')::date,
           try_to_timestamp_ntz(begin_date_raw, 'YYYY-MM-DD HH24:MI:SS')::date) as begin_date,
 coalesce(try_to_date(nullif(trim(end_date_raw), ''), 'YYYY-MM-DD'),
           try_to_date(nullif(trim(end_date_raw), ''), 'MM/DD/YYYY'),
           try_to_timestamp_ntz(end_date_raw, 'YYYY-MM-DD"T"HH24:MI:SS')::date,
           try_to_timestamp_ntz(end_date_raw, 'YYYY-MM-DD HH24:MI:SS')::date) as end_date,
 case
 when regexp_like(trim(soc_code_raw), '[0-9]{2}-[0-9]{4}([.][0-9]{2})?') then substr(trim(soc_code_raw),1,7)
 when regexp_like(trim(soc_code_raw), '[0-9]{6}') then substr(trim(soc_code_raw),1,2)||'-'||substr(trim(soc_code_raw),3,4)
 else null end as soc_code,
 upper(trim(employer_state_raw)) as employer_state,
 upper(trim(worksite_state_raw)) as worksite_state,
 upper(trim(regexp_replace(replace(replace(worksite_county_raw, '.', ''), chr(39), ''), '[[:space:]]+', ' '))) as worksite_county,
 upper(trim(regexp_replace(replace(replace(worksite_city_raw, '.', ''), chr(39), ''), '[[:space:]]+', ' '))) as worksite_city,
 -- First five digits of ZIP / ZIP+4; 4-digit values lost their leading zero in the source.
 case when regexp_like(trim(worksite_postal_code_raw), '[0-9]{5}(-?[0-9]{4})?')
      then left(trim(worksite_postal_code_raw), 5)
      when regexp_like(trim(worksite_postal_code_raw), '[0-9]{4}')
      then '0' || trim(worksite_postal_code_raw) end as worksite_zip5,
 try_to_decimal(wage_amount_raw, 18, 2) as wage_amount,
 case when regexp_like(trim(worker_positions_raw), '[+-]?[0-9]+([.]0+)?')
 then try_to_decimal(trim(worker_positions_raw), 38, 0) else null end as worker_positions
 from mapped
)
-- County comes from the source county name; when that is missing or unmatched, from the
-- worksite ZIP via the Census2020 ZCTA -> county seed (one county or >= 90% of the land,
-- same state only), then from the worksite city via the Census2020 place -> county seed
-- (single-county names only).
select t.*, md5(coalesce(employer_country,'')||'|'||coalesce(employer_name,'')||'|'||coalesce(employer_state,'')||'|'||coalesce(employer_fein,'')||'|'||coalesce(employer_city,'')||'|'||coalesce(employer_zip,'')) as source_employer_key, (cast(t.wage_amount as decimal(18,2)) *
 case t.wage_unit
   when 'Hour' then 2080 when 'Week' then 52 when 'Bi-Weekly' then 26
   when 'Month' then 12 when 'Year' then 1 else null
 end)::decimal(24,2) as annual_wage,
 s.state_fips,
 coalesce(c.county_fips, z.county_fips, p.county_fips) as county_fips,
 coalesce(c.geography_vintage, z.geography_vintage, p.geography_vintage) as geography_vintage,
 case when c.county_fips is not null then 'MATCHED'
      when z.county_fips is not null then 'MATCHED_FROM_ZIP'
      when p.county_fips is not null then 'MATCHED_FROM_CITY'
      when t.worksite_county is null then 'SOURCE_COUNTY_MISSING'
      else 'UNRESOLVED_COUNTY' end as geography_status,
 case when c.county_fips is not null then 'SOURCE_COUNTY'
      else coalesce(z.match_rule, p.match_rule) end as county_match_rule,
 c.county_fips is null and z.county_fips is null and p.county_fips is null as geo_unresolved,
 t.soc_code is null as soc_unresolved
from typed t
left join ANALYTICS.STAGING.state_fips s on s.state_code = t.worksite_state
left join ANALYTICS.STAGING.county_fips c
 on c.state_code = t.worksite_state and c.county_name = t.worksite_county
left join ANALYTICS.STAGING.zcta_county_fips z
 on z.zcta = t.worksite_zip5 and z.state_fips = s.state_fips
left join ANALYTICS.STAGING.place_county_fips p
 on p.state_code = t.worksite_state and p.place_name = t.worksite_city
